-- One account per password-login email. Created after
-- 20261026150000_lowercase_emails, so it is built on lowercased data and
-- 'Jane@x.com' / 'jane@x.com' collide. Unique only among password logins
-- (method = 'local'); provider rows' emails are information and may repeat.
-- Generated by `prisma migrate diff` from the schema's
-- @@unique([email], map: "UQ_login_methods_local_email", where: { method: "local" }).

-- CreateIndex
CREATE UNIQUE INDEX "UQ_login_methods_local_email" ON "user_login_methods"("email") WHERE ("method" = 'local');
